import { useMemo, useState } from "react";
import { ArrowDownToLine, ArrowUpRight, Check, CheckCircle2, ChevronRight, Clock3, Download, FileCheck2, Filter, Layers3, MapPinned, MoreHorizontal, Play, Plus, RotateCcw, ScanSearch, Satellite, Search, ShieldAlert, SlidersHorizontal, Sparkles, TrendingUp, UserRound, X } from "lucide-react";
import { useLocation } from "wouter";
import { toast } from "sonner";
import { PortalShell } from "@/components/PortalShell";
import { ParcelMapPreview } from "@/components/ParcelMapPreview";
import { ModuleHeader, ModuleStat, PillTabs, SearchField, SectionCard, StatePanel } from "@/components/ModulePrimitives";
import { auditLogs, demoParcels, reports, satelliteObservations, validationResults } from "@/lib/demoData";
import { makeWorkflowEvent } from "@/lib/workflowState";
import { useLandStack } from "@/contexts/LandStackContext";

const parcelTabs = ["Identity", "Ownership / Rights", "Registration", "Planning", "Legal / Liability", "Financial", "Infrastructure", "Environment", "AI / Monitoring"];

export function GovernmentWorkspace() {
  const [location] = useLocation();
  if (location === "/government/gis" || location === "/gis-explorer") return <GovernmentPage><GISExplorer /></GovernmentPage>;
  if (location === "/government/parcel" || location.startsWith("/government/parcel/")) return <GovernmentPage><Parcel360 /></GovernmentPage>;
  if (location === "/government/validation") return <GovernmentPage><AIValidation /></GovernmentPage>;
  if (location === "/government/satellite") return <GovernmentPage><SatelliteMonitoring /></GovernmentPage>;
  if (location === "/government/review") return <GovernmentPage><ReviewWorkspace /></GovernmentPage>;
  if (location === "/government/reports") return <GovernmentPage><ReportsPage /></GovernmentPage>;
  if (location === "/government/analytics") return <GovernmentPage><AnalyticsPage /></GovernmentPage>;
  if (location === "/government/audit") return <GovernmentPage><AuditPage /></GovernmentPage>;
  return null;
}

function GovernmentPage({ children }: { children: React.ReactNode }) { return <PortalShell role="government"><div className="module-page">{children}</div></PortalShell>; }

function GISExplorer() {
  const { selectedParcel, selectParcel, setSelectedParcelDetail, mapLayer, setMapLayer } = useLandStack();
  const [, setLocation] = useLocation();
  const [search, setSearch] = useState("");
  const [landUse, setLandUse] = useState("All land use");
  const [risk, setRisk] = useState("All risk levels");
  const [status, setStatus] = useState("All statuses");

  const [activeGisLayers, setActiveGisLayers] = useState<string[]>([
    "Georeferenced Cadastral Maps", 
    "Parcel Boundaries", 
    "ULPIN / Unique Parcel Identifier"
  ]);

  const toggleGisLayer = (layer: string) => {
    setActiveGisLayers((prev) => 
      prev.includes(layer) ? prev.filter((l) => l !== layer) : [...prev, layer]
    );
  };
  const filtered = demoParcels.filter((parcel) => {
    const demoAlias = parcel.id === "LS-AP-0428-019" ? "LS-PAR-0428" : "";
    const matchesSearch = `${parcel.id} ${demoAlias} ${parcel.ulpin} ${parcel.owner} ${parcel.locality}`.toLowerCase().includes(search.toLowerCase());
    const matchesLandUse = landUse === "All land use" || parcel.landUse === landUse;
    const matchesRisk = risk === "All risk levels" || parcel.risk === risk;
    const matchesStatus = status === "All statuses" || parcel.status === status;
    return matchesSearch && matchesLandUse && matchesRisk && matchesStatus;
  });

  const ownershipStatus = selectedParcel.details?.ownership.ownershipType ?? (selectedParcel.status === "Flagged" ? "Under review" : "Verified");
  const regStatus = selectedParcel.details?.registration.status ?? "Verified";
  const taxStatus = selectedParcel.details?.propertyTax.paymentStatus ?? "Up to date";
  const encStatus = selectedParcel.details?.encumbrance.status ?? (selectedParcel.id.endsWith("021") ? "Under review" : "None detected");
  const valStatus = selectedParcel.details?.validation.status ?? (selectedParcel.status === "Flagged" ? "Flagged" : selectedParcel.status === "Under review" ? "Needs review" : "Verified");

  return <><ModuleHeader eyebrow="GOVERNMENT / GIS EXPLORER" title="Explore the land fabric." description="Inspect synthetic parcel boundaries, switch intelligence layers and open a parcel identity from the map." actions={<><SearchField value={search} onChange={setSearch} placeholder="Search parcel or ULPIN" /><button className="secondary-button" onClick={() => { setSearch(""); setLandUse("All land use"); setRisk("All risk levels"); setStatus("All statuses"); toast.info("Map extent and filters reset"); }}><RotateCcw size={14} /> Reset extent</button></>} /><div className="gis-workspace"><aside className="gis-layer-panel surface-card" style={{ overflowY: 'auto' }}><div className="card-kicker">MAP LAYERS</div><h2>Intelligence layers</h2><p>Switch a layer to change the map context.</p><div className="layer-group"><div className="card-kicker">BASE / FOUNDATIONAL LAYERS</div>{["Georeferenced Cadastral Maps", "Parcel Boundaries", "ULPIN / Unique Parcel Identifier"].map((layer) => <button key={layer} className={`layer-row ${activeGisLayers.includes(layer) ? "layer-row-active" : ""}`} onClick={() => toggleGisLayer(layer)}><span className="layer-symbol"><Layers3 size={14} /></span><span><strong>{layer}</strong><small>{activeGisLayers.includes(layer) ? "ON" : "OFF"}</small></span><span className="layer-toggle" /></button>)}</div><div className="layer-group" style={{ marginTop: '1rem' }}><div className="card-kicker">ESSENTIAL / CORE GOVERNANCE LAYERS</div>{["Record of Rights (RoR)", "Registration Data", "Master Plans", "Building Permissions & Approvals", "Encumbrance & Mortgage Records", "Land Use & Zoning"].map((layer) => <button key={layer} className={`layer-row ${activeGisLayers.includes(layer) ? "layer-row-active" : ""}`} onClick={() => toggleGisLayer(layer)}><span className="layer-symbol"><Layers3 size={14} /></span><span><strong>{layer}</strong><small>{activeGisLayers.includes(layer) ? "ON" : "OFF"}</small></span><span className="layer-toggle" /></button>)}</div><div className="layer-group" style={{ marginTop: '1rem' }}><div className="card-kicker">ADDITIONAL / USE-CASE LAYERS</div>{["Utility Infrastructure", "Property Taxation Records", "Valuation References", "Infrastructure Networks", "Environmental Zones", "Restriction Zones", "Other Service Linkages"].map((layer) => <button key={layer} className={`layer-row ${activeGisLayers.includes(layer) ? "layer-row-active" : ""}`} onClick={() => toggleGisLayer(layer)}><span className="layer-symbol"><Layers3 size={14} /></span><span><strong>{layer}</strong><small>{activeGisLayers.includes(layer) ? "ON" : "OFF"}</small></span><span className="layer-toggle" /></button>)}</div><div className="gis-filter-controls"><div className="card-kicker">FILTER PARCELS</div><select value={landUse} onChange={(event) => setLandUse(event.target.value)} aria-label="Filter by land use"><option>All land use</option><option>Residential</option><option>Mixed use</option><option>Agricultural</option><option>Institutional</option><option>Commercial</option></select><select value={risk} onChange={(event) => setRisk(event.target.value)} aria-label="Filter by risk level"><option>All risk levels</option><option>Low</option><option>Medium</option><option>High</option></select><select value={status} onChange={(event) => setStatus(event.target.value)} aria-label="Filter by validation status"><option>All statuses</option><option>Verified</option><option>Under review</option><option>Flagged</option></select></div><div className="layer-note"><Sparkles size={14} /><span><strong>MapLibre-ready</strong>GeoJSON source boundary is prepared for a real tile service.</span></div><div className="map-extent-list"><div className="card-kicker">VISIBLE PARCELS <span>{filtered.length}</span></div>{filtered.map((parcel) => <button key={parcel.id} onClick={() => selectParcel(parcel.id, parcel)} className={selectedParcel.id.toLowerCase() === parcel.id.toLowerCase() ? "extent-row-active" : ""}><span className={`extent-risk extent-risk-${parcel.risk.toLowerCase()}`} /><span><strong>{parcel.id}</strong><small>{parcel.locality}</small></span><ChevronRight size={14} /></button>)}</div></aside><div className="gis-canvas-wrap"><ParcelMapPreview selectedParcel={selectedParcel} onSelect={(parcel) => selectParcel(parcel.id, parcel)} onParcelDetail={setSelectedParcelDetail} activeLayer={mapLayer} onLayerChange={setMapLayer} activeGisLayers={activeGisLayers} /><div className="gis-canvas-footer"><span><span className="live-dot" /> Synthetic district extent · 5 parcels loaded</span><span className="mono-text">GeoJSON · EPSG:4326</span></div></div><aside className="gis-selected-panel surface-card"><div className="selected-panel-kicker"><MapPinned size={14} /> SELECTED FEATURE</div><div className="selected-panel-title"><div className="feature-avatar"><Layers3 size={20} /></div><div><span className="mono-text">{selectedParcel.id}</span><h2>{selectedParcel.locality}</h2></div></div><span className={`status-badge ${selectedParcel.status === "Verified" ? "status-verified" : selectedParcel.status === "Flagged" ? "status-flagged" : "status-review"}`}><span />{selectedParcel.status}</span><div className="feature-grid"><div><span>ULPIN</span><strong className="mono-text">{selectedParcel.ulpin}</strong></div><div><span>Area</span><strong>{selectedParcel.area}</strong></div><div><span>Land use</span><strong>{selectedParcel.landUse}</strong></div><div><span>Risk level</span><strong className={`risk-text-${selectedParcel.risk.toLowerCase()}`}>{selectedParcel.risk}</strong></div><div><span>Owner</span><strong>{selectedParcel.owner}</strong></div><div><span>Location</span><strong>{selectedParcel.locality}</strong></div></div><div className="quick-indicators"><span className={ownershipStatus === "Disputed" || ownershipStatus === "Flagged" ? "quick-indicator-flagged" : ownershipStatus === "Under review" ? "quick-indicator-review" : ""}><CheckCircle2 size={12} /> {selectedParcel.details?.ownership.ownershipType ? `Ownership: ${selectedParcel.details.ownership.ownershipType}` : "Ownership"}</span><span className={regStatus === "Disputed" || regStatus === "Flagged" ? "quick-indicator-flagged" : regStatus === "Under review" || regStatus === "Pending" ? "quick-indicator-review" : ""}><CheckCircle2 size={12} /> {selectedParcel.details?.registration.status ? `Registration: ${selectedParcel.details.registration.status}` : "Registration"}</span><span className={taxStatus === "Overdue" || taxStatus === "Defaulted" ? "quick-indicator-flagged" : taxStatus === "Pending" ? "quick-indicator-review" : ""}><CheckCircle2 size={12} /> {selectedParcel.details?.propertyTax.paymentStatus ? `Tax: ${selectedParcel.details.propertyTax.paymentStatus}` : "Tax"}</span><span className={(!selectedParcel.details?.encumbrance.status || selectedParcel.details?.encumbrance.status === "None detected" || selectedParcel.details?.encumbrance.status === "Clear") && !selectedParcel.id.endsWith("021") ? "" : (selectedParcel.details?.encumbrance.status === "High" ? "quick-indicator-flagged" : "quick-indicator-review")}><CheckCircle2 size={12} /> {selectedParcel.details?.encumbrance.status ? `Encumbrance: ${selectedParcel.details.encumbrance.status}` : "Encumbrance"}</span><span className={valStatus === "Flagged" || valStatus === "High" ? "quick-indicator-flagged" : valStatus === "Under review" || valStatus === "Needs review" || valStatus === "Medium" ? "quick-indicator-review" : ""}><Clock3 size={12} /> {selectedParcel.details?.validation.status ? `Validation: ${selectedParcel.details.validation.status}` : "Validation"}</span></div><button className="primary-button feature-action" onClick={() => { setLocation("/government/parcel"); toast.success(`${selectedParcel.id} opened in Parcel 360°`); }}><Layers3 size={15} /> Open Parcel 360° <ArrowUpRight size={14} /></button><button className="secondary-button feature-action" onClick={() => setLocation("/government/validation")}><ScanSearch size={15} /> View AI Validation</button></aside></div></>;
}

function Parcel360() {
  const { selectedParcel } = useLandStack();
  const [, setLocation] = useLocation();
  const [activeTab, setActiveTab] = useState("Identity");
  const parcelValidations = validationResults.filter((item) => item.parcelId === selectedParcel.id);
  const parcelSatellite = satelliteObservations.find((item) => item.parcelId === selectedParcel.id);
  const overallRisk = selectedParcel.risk;
  const tabContent: Record<string, React.ReactNode> = {
    "Identity": <RecordGrid records={[["Parcel ID", selectedParcel.id], ["ULPIN", selectedParcel.ulpin], ["Area", selectedParcel.area], ["Location", selectedParcel.locality], ["Land Use", selectedParcel.landUse]]} />,
    "Ownership / Rights": <RecordGrid records={[["Owner", selectedParcel.details?.ownership?.ownerName ?? selectedParcel.owner], ["Ownership type", selectedParcel.details?.ownership?.ownershipType ?? "Recorded owner"], ["Co-owners", (selectedParcel.details?.ownership?.coOwnerCount ?? 0).toString()], ["Ownership Record", selectedParcel.details?.ownership?.label ?? "Verified"]]} />,
    "Registration": <RecordGrid records={[["Status", selectedParcel.details?.registration?.status ?? "Verified"], ["Record Type", selectedParcel.details?.registration?.recordType ?? "Sale Deed"], ["Record Number", selectedParcel.details?.registration?.recordNumber ?? "REG-101"], ["Authority", selectedParcel.details?.registration?.issuingAuthority ?? "Sub-Registrar"]]} />,
    "Planning": <RecordGrid records={[["Master Plan", "Residential Zone"], ["Zoning", "R-1"], ["Building Permission", "Approved"], ["Application ID", "BP-DEMO-2024-081"]]} />,
    "Legal / Liability": <RecordGrid records={[["Encumbrance status", selectedParcel.details?.encumbrance?.status ?? "None detected"], ["Type", selectedParcel.details?.encumbrance?.encumbranceType ?? "—"], ["Holder", selectedParcel.details?.encumbrance?.holderName ?? "—"], ["Restrictions", (selectedParcel.details?.restrictions?.length ?? 0) > 0 ? selectedParcel.details!.restrictions.join(", ") : "None"]]} />,
    "Financial": <RecordGrid records={[["Tax Payment Status", selectedParcel.details?.propertyTax?.paymentStatus ?? "Up to date"], ["Assessment Year", selectedParcel.details?.propertyTax?.assessmentYear ?? "2026-27"], ["Amount Due", selectedParcel.details?.propertyTax?.amountDue ? `₹ ${selectedParcel.details.propertyTax.amountDue}` : "₹ 0"], ["Valuation Reference", selectedParcel.details?.propertyTax?.label ?? "VAL-2025-091"]]} />,
    "Infrastructure": <RecordGrid records={[["Utilities", "Electricity, Water connected"], ["Infrastructure networks", "Active"]]} />,
    "Environment": <RecordGrid records={[["Environmental Zone", "Clear"], ["Restriction zone information", (selectedParcel.details?.restrictions?.length ?? 0) > 0 ? "Present" : "None"]]} />,
    "AI / Monitoring": <ValidationSummary parcelId={selectedParcel.id} validations={parcelValidations} onOpen={() => setLocation("/government/validation")} />,
  };
  const report = () => toast.success("Parcel report generated", { description: `${selectedParcel.id} · synthetic data preview ready in Reports.` });
  return <><ModuleHeader eyebrow="GOVERNMENT / PARCEL 360°" title="Parcel 360°" description="One parcel identity across ownership, records, land use, risk and monitoring context." actions={<><button className="secondary-button" onClick={() => setLocation("/government/gis")}><MapPinned size={14} /> View on GIS</button><button className="secondary-button" onClick={report}><Download size={14} /> Generate report</button><button className="primary-button" onClick={() => setLocation("/government/review")}><CheckCircle2 size={14} /> Review case</button></>} /><div className="parcel-360-header surface-card"><div className="parcel-360-header-main"><div className="parcel-id-row"><span className="mono-text">{selectedParcel.id}</span><span className={`status-badge ${selectedParcel.status === "Verified" ? "status-verified" : selectedParcel.status === "Flagged" ? "status-flagged" : "status-review"}`}><span />{selectedParcel.status}</span></div><h2>{selectedParcel.locality}</h2><div className="parcel-360-meta"><span className="mono-text">ULPIN · {selectedParcel.ulpin}</span><span>{selectedParcel.area}</span><span>{selectedParcel.landUse}</span><span>{selectedParcel.coordinates}</span></div></div><div className="parcel-360-header-actions"><button onClick={() => setLocation("/government/gis")}><MapPinned size={14} /> View on Map</button><button onClick={() => setLocation("/government/validation")}><ScanSearch size={14} /> AI Validation</button><button onClick={() => setLocation("/government/satellite")}><Satellite size={14} /> Satellite Monitoring</button></div></div><div className="parcel-summary-grid"><SummaryCard label="Parcel area" value={selectedParcel.area} source="GIS" /><SummaryCard label="Land use" value={selectedParcel.landUse} source="Land-use" /><SummaryCard label="Ownership" value="Verified" tone="green" source="RoR" /><SummaryCard label="Registration" value="Verified" tone="green" source="Registration" /><SummaryCard label="Encumbrance" value={selectedParcel.id.endsWith("021") ? "Under review" : "None detected"} tone={selectedParcel.id.endsWith("021") ? "amber" : "green"} source="Registry" /><SummaryCard label="Property tax" value="Up to date" tone="green" source="Tax" /><SummaryCard label="AI risk" value={overallRisk} tone={overallRisk === "High" ? "red" : overallRisk === "Medium" ? "amber" : "green"} source="AI rules" /><SummaryCard label="Last updated" value={selectedParcel.lastUpdated} source="Audit" /></div><div className="parcel-360-main-grid"><div className="parcel-360-left"><SectionCard title="Selected parcel map" kicker="GIS CONTEXT" action={<button className="card-link" onClick={() => setLocation("/government/gis")}>Open in GIS Explorer <ArrowUpRight size={13} /></button>}><div className="parcel-360-map"><ParcelMapPreview selectedParcel={selectedParcel} onSelect={() => undefined} compact /></div></SectionCard><SectionCard title="Parcel identity" kicker="OVERVIEW"><OverviewRecord parcel={selectedParcel} /></SectionCard><SectionCard title="Land Records" kicker="SOURCE RECORDS"><LandRecords parcelId={selectedParcel.id} onReport={report} /></SectionCard></div><div className="parcel-360-right"><SectionCard title="Parcel Risk Summary" kicker="RISK INDICATORS"><RiskSummary overall={overallRisk} parcel={selectedParcel} /></SectionCard><SectionCard title="AI Validation Summary" kicker="HUMAN REVIEW"><ValidationSummary parcelId={selectedParcel.id} validations={parcelValidations} onOpen={() => setLocation("/government/validation")} /></SectionCard><SectionCard title="Satellite Monitoring" kicker="LATEST OBSERVATION"><SatelliteSummary parcelId={selectedParcel.id} observation={parcelSatellite} onOpen={() => setLocation("/government/satellite")} /></SectionCard></div></div><div className="parcel-tabs-wrap"><PillTabs tabs={parcelTabs} active={activeTab} onChange={setActiveTab} /></div><div className="parcel-tab-layout"><SectionCard title={activeTab} kicker="PARCEL INTELLIGENCE"><div className="tab-content">{activeTab === "Overview" ? <OverviewTab parcel={selectedParcel} validations={parcelValidations} observation={parcelSatellite} onReport={report} /> : tabContent[activeTab]}</div></SectionCard><SectionCard title="Quick actions" kicker="WORKFLOW"><div className="quick-action-list"><button onClick={() => setLocation("/government/gis")}><MapPinned size={14} /> View on GIS <ArrowUpRight size={13} /></button><button onClick={() => setLocation("/government/validation")}><ScanSearch size={14} /> AI Validation <ArrowUpRight size={13} /></button><button onClick={() => setLocation("/government/satellite")}><Satellite size={14} /> Satellite Monitoring <ArrowUpRight size={13} /></button><button onClick={() => setLocation("/government/review")}><CheckCircle2 size={14} /> Review Case <ArrowUpRight size={13} /></button><button onClick={report}><Download size={14} /> Generate Report <ArrowUpRight size={13} /></button></div></SectionCard></div></>;
}

function SummaryCard({ label, value, source, tone = "blue" }: { label: string; value: string; source: string; tone?: string }) { return <div className={`parcel-summary-card parcel-summary-${tone}`}><span>{label}</span><strong>{value}</strong><small>{source}</small></div>; }
function OverviewTab({ parcel, validations, observation, onReport }: { parcel: typeof demoParcels[number]; validations: typeof validationResults; observation?: typeof satelliteObservations[number]; onReport: () => void }) { return <div className="overview-tab-content"><div className="overview-record-grid"><div><span>Parcel identity</span><strong className="mono-text">{parcel.id}</strong></div><div><span>ULPIN</span><strong className="mono-text">{parcel.ulpin}</strong></div><div><span>Owner</span><strong>{parcel.owner}</strong></div><div><span>Location</span><strong>{parcel.locality}</strong></div><div><span>Area</span><strong>{parcel.area}</strong></div><div><span>Land use</span><strong>{parcel.landUse}</strong></div><div><span>Ownership</span><strong>Verified · RoR matched</strong></div><div><span>Risk</span><strong className={`risk-text-${parcel.risk.toLowerCase()}`}>{parcel.risk}</strong></div></div><div className="overview-source-row"><span className="source-badge">GIS geometry</span><span className="source-badge">RoR</span><span className="source-badge">Registration</span><span className="source-badge">Tax</span><span className="source-badge">AI Validation</span><span className="source-badge">Satellite</span></div><div className="parcel-timeline"><div className="card-kicker">PARCEL INTELLIGENCE TIMELINE</div><TimelineEvent year="2019" title="Ownership record created" source="RoR" /><TimelineEvent year="2021" title="Registration updated" source="Registration" /><TimelineEvent year="2023" title="Property tax verified" source="Tax" /><TimelineEvent year="2025" title="Land-use record updated" source="Land-use" /><TimelineEvent year="2026" title={validations.length ? "AI validation requires review" : "AI validation completed"} source="AI Validation" tone={validations.length ? "amber" : "green"} /><TimelineEvent year="2026" title={observation ? `Satellite observation · ${observation.changeType}` : "Satellite observation reviewed"} source="Satellite" tone={observation?.reviewStatus === "Needs review" ? "amber" : "green"} /></div><div className="overview-demo-note"><Sparkles size={14} /><span><strong>Synthetic demonstration record</strong>All values are Data designed to show how one parcel identity connects multiple land-intelligence sources.</span><button className="card-link" onClick={onReport}>Generate parcel report <ArrowUpRight size={13} /></button></div></div>; }
function LandRecords({ parcelId, onReport }: { parcelId: string; onReport: () => void }) { const records = [["Record of Rights", `ROR-${parcelId.slice(-4)}-DEMO`, "12 Sep 2026", "Verified", "RoR"], ["Ownership Record", `OWN-${parcelId.slice(-4)}-2021`, "01 Apr 2021", "Verified", "Registration"], ["Registration extract", `REG-${parcelId.slice(-4)}-77891`, "16 Jun 2024", "Available", "Registry"], ["Property tax receipt", `TAX-${parcelId.slice(-4)}-0881`, "22 Jul 2026", "Paid", "Tax"]]; return <div className="land-record-list">{records.map(([type, number, date, status, source]) => <div className="land-record-row" key={type}><div className="record-file-icon"><FileCheck2 size={15} /></div><div><strong>{type}</strong><span className="mono-text">{number}</span></div><span>{date}</span><span className="status-badge status-verified"><span />{status}</span><small className="source-badge">{source}</small><button className="table-more" onClick={() => toast.info(`${type} preview opened in Citizen mode`)}><ArrowUpRight size={14} /></button></div>)}<button className="card-link" onClick={onReport}>Generate a parcel report from these records <ArrowUpRight size={13} /></button></div>; }
function TransactionTimeline({ parcelId }: { parcelId: string }) { return <div className="transaction-timeline"><TimelineEvent year="16 Jun 2024" title="Mutation registered" source={`TXN-${parcelId.slice(-4)}-0482`} /><TimelineEvent year="03 Mar 2022" title="Ownership transfer recorded" source="Synthetic registration" /><TimelineEvent year="01 Apr 2021" title="Ownership record created" source="Synthetic RoR" /></div>; }
function LandUseRecord({ parcel }: { parcel: typeof demoParcels[number] }) { return <div className="land-use-detail"><div className="land-use-current"><span>Current land use</span><strong>{parcel.landUse}</strong><em>Verified</em></div><RecordGrid records={[["Previous land use", "Agricultural"], ["Classification", "Residential corridor"], ["Effective date", "01 Jan 2025"], ["Source", "Synthetic land-use layer"]]} /><div className="land-use-history"><span>2021</span><i /><strong>Agricultural</strong><span>2025</span><i /><strong>{parcel.landUse}</strong></div></div>; }
function RiskSummary({ overall, parcel }: { overall: string; parcel: typeof demoParcels[number] }) { const items = [["Overall risk", overall], ["Ownership risk", "Low"], ["Land-use risk", parcel.status === "Flagged" ? "High" : "Medium"], ["Document risk", "Low"], ["Transaction risk", "Low"], ["Restriction risk", parcel.id.endsWith("021") ? "Medium" : "Low"], ["Satellite risk", "Medium"]]; return <div className="risk-summary-list">{items.map(([label, value]) => <div key={label}><span>{label}</span><strong className={`risk-text-${value.toLowerCase()}`}>{value}</strong><i><b className={`risk-bar-${value.toLowerCase()}`} /></i></div>)}<small>Rule-based demonstration indicators, not a government decision.</small></div>; }
function ValidationSummary({ parcelId, validations, onOpen }: { parcelId: string; validations: typeof validationResults; onOpen: () => void }) { const issueCount = validations.length; const highest = validations.some((item) => item.riskLevel === "High") ? "High" : issueCount ? "Medium" : "Low"; return <div className="validation-summary"><div className="validation-summary-top"><span className={`risk-badge risk-${highest.toLowerCase()}`}>{highest} risk</span><span className={`status-badge ${issueCount ? "status-review" : "status-verified"}`}><span />{issueCount ? "Needs review" : "Verified"}</span></div><div className="validation-summary-grid"><div><span>Validation status</span><strong>{issueCount ? "Needs review" : "Verified"}</strong></div><div><span>Issues detected</span><strong>{issueCount}</strong></div><div><span>Last validation</span><strong>16 Sep 2026</strong></div></div>{issueCount ? <div className="human-review-note"><ShieldAlert size={14} /><span><strong>Human Review Required</strong>{validations[0].issueType} · {validations[0].description}</span></div> : <div className="validation-clear-note"><Check size={14} /> No active validation issues for {parcelId}.</div>}<button className="card-link" onClick={onOpen}>Open AI Validation <ArrowUpRight size={13} /></button></div>; }
function SatelliteSummary({ parcelId, observation, onOpen }: { parcelId: string; observation?: typeof satelliteObservations[number]; onOpen: () => void }) { return <div className="satellite-summary"><div className="satellite-summary-icon"><Satellite size={17} /></div><div className="satellite-summary-copy"><span>Last observation</span><strong>{observation?.captureDate ?? "12 Sep 2026"}</strong><small>{observation?.changeType ?? "No material change"}</small></div><span className={`status-badge ${observation?.reviewStatus === "Needs review" ? "status-review" : "status-verified"}`}><span />{observation?.reviewStatus ?? "Clear"}</span><button className="card-link" onClick={onOpen}>View Satellite Monitoring <ArrowUpRight size={13} /></button></div>; }
function TimelineEvent({ year, title, source, tone = "blue" }: { year: string; title: string; source: string; tone?: string }) { return <div className="timeline-event"><span className="timeline-year">{year}</span><i className={`timeline-dot timeline-dot-${tone}`} /><div><strong>{title}</strong><small className="source-badge">{source}</small></div></div>; }

function OverviewRecord({ parcel }: { parcel: typeof demoParcels[number] }) { return <div className="overview-record-grid">{[["ULPIN", parcel.ulpin], ["Owner", parcel.owner], ["Area", parcel.area], ["Location", parcel.locality], ["Land use", parcel.landUse], ["Ownership status", "Recorded owner"]].map(([label, value]) => <div key={label}><span>{label}</span><strong className={label === "ULPIN" ? "mono-text" : ""}>{value}</strong></div>)}</div>; }
function RecordGrid({ records }: { records: string[][] }) { return <div className="record-grid">{records.map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>; }
function ValidationMini() { return <div className="validation-mini"><span className="status-badge status-review"><span />1 item in review</span><strong>Land-use mismatch</strong><p>Synthetic master-plan comparison requires a human check.</p><button className="card-link" onClick={() => toast.info("Opening AI validation workspace")}>Open validation queue <ArrowUpRight size={14} /></button></div>; }

function AIValidation() {
  const { selectedParcel, selectParcel } = useLandStack();
  const [, setLocation] = useLocation();
  const parcelMatches = validationResults.filter((item) => item.parcelId === selectedParcel.id);
  const [scope, setScope] = useState<"parcel" | "all">(parcelMatches.length ? "parcel" : "all");
  const [selectedId, setSelectedId] = useState(parcelMatches[0]?.id ?? validationResults[0]?.id ?? "");
  const [issueFilter, setIssueFilter] = useState("All issue types");
  const [riskFilter, setRiskFilter] = useState("All risk levels");
  const [statusFilter, setStatusFilter] = useState("All statuses");
  const source = scope === "parcel" ? parcelMatches : validationResults;
  const visible = source.filter((item) => (issueFilter === "All issue types" || item.issueType === issueFilter) && (riskFilter === "All risk levels" || item.riskLevel === riskFilter) && (statusFilter === "All statuses" || item.status === statusFilter));
  const selected = visible.find((item) => item.id === selectedId) ?? visible[0];
  const openItem = (item: typeof validationResults[number]) => { setSelectedId(item.id); selectParcel(item.parcelId); };
  return <><ModuleHeader eyebrow="GOVERNMENT / AI VALIDATION" title="AI Validation" description="Assistive validation across land records. Findings are possible inconsistencies that always require human review." actions={<><button className="secondary-button" onClick={() => setScope(scope === "parcel" ? "all" : "parcel")}>{scope === "parcel" ? "View All Validations" : "Validations for this Parcel"}</button><button className="primary-button" onClick={() => toast.info("Validation batch queued as a Background task")}><Play size={14} /> Run validation batch</button></>} /><div className="module-stat-grid validation-stat-grid"><ModuleStat label="Total validations" value="1,284" detail="Synthetic checks" icon={<ScanSearch size={16} />} /><ModuleStat label="Issues detected" value="34" detail="Potential inconsistencies" tone="amber" icon={<ShieldAlert size={16} />} /><ModuleStat label="High risk" value="08" detail="Priority review" tone="red" icon={<ShieldAlert size={16} />} /><ModuleStat label="Medium risk" value="19" detail="Requires verification" tone="amber" icon={<ScanSearch size={16} />} /><ModuleStat label="Pending review" value="12" detail="Human action needed" tone="teal" icon={<Clock3 size={16} />} /><ModuleStat label="Verified" value="1,250" detail="No issue detected" tone="green" icon={<CheckCircle2 size={16} />} /></div><div className="workflow-strip"><div className="workflow-step workflow-active"><span>01</span><strong>AI detection</strong><small>Possible signal</small></div><ChevronRight /><div className="workflow-step"><span>02</span><strong>Needs review</strong><small>Officer evaluates evidence</small></div><ChevronRight /><div className="workflow-step"><span>03</span><strong>Approve / escalate</strong><small>Government decision</small></div><div className="workflow-note"><Sparkles size={15} /> AI assists. Officers decide.</div></div><div className="validation-workspace"><SectionCard title={scope === "parcel" ? `Validations for ${selectedParcel.id}` : "All validation findings"} kicker={scope === "parcel" ? "SELECTED PARCEL" : "EXPLAINABLE RESULTS"} action={<div className="validation-filter-bar"><select value={issueFilter} onChange={(event) => setIssueFilter(event.target.value)} aria-label="Filter by issue type"><option>All issue types</option><option>Ownership mismatch</option><option>Area mismatch</option><option>Land-use mismatch</option><option>Document inconsistency</option><option>Transaction anomaly</option><option>Restriction conflict</option></select><select value={riskFilter} onChange={(event) => setRiskFilter(event.target.value)} aria-label="Filter by risk"><option>All risk levels</option><option>High</option><option>Medium</option><option>Low</option></select><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} aria-label="Filter by status"><option>All statuses</option><option>Open</option><option>In review</option><option>Resolved</option><option>Dismissed</option></select></div>}>{visible.length ? <div className="validation-table-wrap"><div className="validation-table-head"><span>Parcel / ULPIN</span><span>Issue</span><span>Risk</span><span>Source</span><span>Detected</span><span>Status</span><span /></div>{visible.map((item) => { const parcel = demoParcels.find((candidate) => candidate.id === item.parcelId) ?? demoParcels[0]; return <button key={item.id} className={`validation-table-row ${selected?.id === item.id ? "validation-table-row-active" : ""}`} onClick={() => openItem(item)}><span><strong className="mono-text">{item.parcelId}</strong><small className="mono-text">{parcel.ulpin}</small></span><span><strong>{item.issueType}</strong><small>{item.description}</small></span><span className={`risk-badge risk-${item.riskLevel.toLowerCase()}`}>{item.riskLevel}</span><span>{item.source}</span><span>{item.createdAt.slice(0, 10)}</span><span className="status-badge status-review"><span />{item.status}</span><ArrowUpRight size={13} /></button>; })}</div> : <StatePanel kind="empty" title="No validation issues found" detail="Try another scope or filter. No issue does not mean a final government decision." />}</SectionCard><ValidationDetail item={selected} onOpenParcel={() => selected && setLocation("/government/parcel")} onOpenReview={() => setLocation("/government/review")} /></div></>;
}

function ValidationDetail({ item, onOpenParcel, onOpenReview }: { item?: typeof validationResults[number]; onOpenParcel: () => void; onOpenReview: () => void }) { if (!item) return <SectionCard title="Selected validation" kicker="DETAIL"><StatePanel kind="empty" title="Select a validation result" detail="Choose a row to inspect AI finding, evidence and recommended human action." /></SectionCard>; const parcel = demoParcels.find((candidate) => candidate.id === item.parcelId) ?? demoParcels[0]; return <SectionCard title="Selected validation" kicker="HUMAN REVIEW DETAIL"><div className="validation-detail-head"><div className={`validation-severity severity-${item.riskLevel.toLowerCase()}`}><ShieldAlert size={17} /></div><div><strong>{item.issueType}</strong><span className="mono-text">{item.id} · {item.parcelId}</span></div><span className={`risk-badge risk-${item.riskLevel.toLowerCase()}`}>{item.riskLevel} risk</span></div><div className="validation-detail-facts"><span>Parcel <strong>{item.parcelId}</strong></span><span>ULPIN <strong className="mono-text">{parcel.ulpin}</strong></span><span>Detected <strong>{item.createdAt.slice(0, 10)}</strong></span><span>Status <strong>{item.status}</strong></span></div><div className="ai-finding-box"><Sparkles size={14} /><div><strong>AI Finding</strong><p>{item.description} This is a review recommendation, not a final determination.</p></div></div><EvidenceComparison issueType={item.issueType} /><div className="source-records"><div className="card-kicker">SOURCE RECORDS</div><span><FileCheck2 size={12} /> {item.source}</span><span><MapPinned size={12} /> GeoJSON parcel geometry</span><span><Clock3 size={12} /> Last synchronized 16 Sep 2026</span></div><div className="detail-actions"><button className="secondary-button" onClick={onOpenParcel}><Layers3 size={14} /> Open Parcel 360°</button><button className="primary-button" onClick={onOpenReview}><CheckCircle2 size={14} /> Open Review</button></div></SectionCard>; }

function EvidenceComparison({ issueType }: { issueType: string }) { const content = issueType === "Ownership mismatch" ? [["Registration Record", "Owner A"], ["RoR Snapshot", "Owner B"]] : issueType === "Document inconsistency" ? [["Document A", "Area = 2.40 acres"], ["Document B", "Area = 2.65 acres"]] : [["Land Record", "Agricultural"], ["GIS / Planning Layer", "Residential"]]; return <div className="evidence-comparison"><div className="card-kicker">EVIDENCE COMPARISON</div><div className="evidence-columns"><div><span>{content[0][0]}</span><strong>{content[0][1]}</strong></div><div className="evidence-vs">VS</div><div><span>{content[1][0]}</span><strong>{content[1][1]}</strong></div></div><small>Potential inconsistency detected · source comparison requires verification.</small></div>; }

function SatelliteMonitoring() {
  const { selectedParcel, selectParcel } = useLandStack();
  const [, setLocation] = useLocation();
  const parcelObservation = satelliteObservations.find((item) => item.parcelId === selectedParcel.id);
  const [selectedId, setSelectedId] = useState(parcelObservation?.id ?? satelliteObservations[0].id);
  const [changeFilter, setChangeFilter] = useState("All change types");
  const [priorityFilter, setPriorityFilter] = useState("All priorities");
  const [statusFilter, setStatusFilter] = useState("All statuses");
  const selected = satelliteObservations.find((item) => item.id === selectedId) ?? parcelObservation ?? satelliteObservations[0];
  const visible = satelliteObservations.filter((item) => (changeFilter === "All change types" || item.changeType === changeFilter) && (priorityFilter === "All priorities" || (item.changePercent > 10 ? "High" : item.changePercent > 5 ? "Medium" : "Low") === priorityFilter) && (statusFilter === "All statuses" || item.reviewStatus === statusFilter));
  const selectObservation = (item: typeof satelliteObservations[number]) => { setSelectedId(item.id); selectParcel(item.parcelId); };
  return <><ModuleHeader eyebrow="GOVERNMENT / SATELLITE MONITORING" title="Satellite Monitoring" description="Synthetic observations help identify possible changes around parcels. They do not represent real satellite analysis." actions={<button className="secondary-button" onClick={() => toast.info("Synthetic observation refresh queued as a Background task")}><Satellite size={14} /> Refresh observations</button>} /><div className="module-stat-grid"><ModuleStat label="Monitored parcels" value="5" detail="Synthetic district extent" icon={<Satellite size={16} />} /><ModuleStat label="Changes detected" value="2" detail="Possible changes" tone="amber" icon={<TrendingUp size={16} />} /><ModuleStat label="High priority" value="1" detail="Needs review" tone="red" icon={<ShieldAlert size={16} />} /><ModuleStat label="Pending review" value="2" detail="Officer action needed" tone="teal" icon={<Clock3 size={16} />} /></div><div className="satellite-selected-strip surface-card"><div className="satellite-selected-icon"><MapPinned size={16} /></div><div><span>SELECTED PARCEL</span><strong className="mono-text">{selectedParcel.id}</strong><small>{selectedParcel.ulpin} · {selectedParcel.area} · {selectedParcel.locality}</small></div><button className="secondary-button" onClick={() => setLocation("/government/parcel")}><Layers3 size={14} /> Open Parcel 360°</button></div><div className="satellite-grid"><SectionCard title="Before / after observation" kicker="SYNTHETIC IMAGERY"><div className="satellite-compare"><div className="satellite-frame satellite-before"><span>BEFORE · 2024-06-15</span><div className="satellite-grid-lines" /><div className="satellite-block block-one" /><div className="satellite-block block-two" /></div><div className="compare-divider"><span>VS</span></div><div className="satellite-frame satellite-after"><span>AFTER · {selected.captureDate}</span><div className="satellite-grid-lines" /><div className="satellite-block block-one" /><div className="satellite-block block-two" /><div className="satellite-new-change" /></div></div><div className="satellite-caption"><span><i className="legend-dot legend-red" /> Possible change highlighted</span><span>Source: {selected.provider}</span></div></SectionCard><SectionCard title="Observation list" kicker="PARCEL MONITORING" action={<div className="satellite-filter-bar"><select value={changeFilter} onChange={(event) => setChangeFilter(event.target.value)} aria-label="Filter by change type"><option>All change types</option><option>Possible land-use change</option><option>New structure</option><option>Vegetation loss</option><option>Boundary change</option><option>No material change</option></select><select value={priorityFilter} onChange={(event) => setPriorityFilter(event.target.value)} aria-label="Filter by priority"><option>All priorities</option><option>High</option><option>Medium</option><option>Low</option></select><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} aria-label="Filter by status"><option>All statuses</option><option>Needs review</option><option>Clear</option><option>Reviewed</option></select></div>}>{visible.length ? <div className="observation-list">{visible.map((observation) => <button key={observation.id} className={`observation-row ${selected.id === observation.id ? "observation-active" : ""}`} onClick={() => selectObservation(observation)}><div className="observation-icon"><Satellite size={15} /></div><div><strong>{observation.parcelId}</strong><span>{observation.changeType} · {observation.changePercent}% area</span></div><span className={`risk-badge risk-${observation.changePercent > 10 ? "high" : observation.changePercent > 5 ? "medium" : "low"}`}>{observation.reviewStatus}</span><ChevronRight size={14} /></button>)}</div> : <StatePanel kind="empty" title="No satellite changes found" detail="Try another observation filter or parcel scope." />}</SectionCard></div><SectionCard title="Selected observation evidence" kicker="CHANGE DETECTION"><div className="observation-detail-grid"><div><span>Affected parcel</span><strong className="mono-text">{selected.parcelId}</strong></div><div><span>ULPIN</span><strong className="mono-text">{demoParcels.find((item) => item.id === selected.parcelId)?.ulpin}</strong></div><div><span>Change type</span><strong>{selected.changeType}</strong></div><div><span>Affected area</span><strong>{selected.changePercent}% of parcel</strong></div><div><span>Detection date</span><strong>{selected.captureDate}</strong></div><div><span>Confidence</span><strong>{Math.round(selected.confidence * 100)}%</strong></div></div><div className="satellite-evidence-note"><Satellite size={14} /><span><strong>Possible change detected</strong> This synthetic observation may connect to a potential land-use mismatch and requires human review.</span></div><div className="detail-actions"><button className="secondary-button" onClick={() => setLocation("/government/parcel")}><Layers3 size={14} /> Open Parcel 360°</button><button className="primary-button" onClick={() => setLocation("/government/validation")}><ScanSearch size={14} /> Open AI Validation</button></div></SectionCard></>;
}

function ReviewWorkspace() {
  const { selectedParcel, selectParcel, workflow, updateWorkflow } = useLandStack();
  const [, setLocation] = useLocation();
  const [selectedId, setSelectedId] = useState(validationResults.find((item) => item.parcelId === workflow.parcelId)?.id ?? validationResults[0].id);
  const [statusFilter, setStatusFilter] = useState("All statuses");
  const [riskFilter, setRiskFilter] = useState("All risks");
  const [issueFilter, setIssueFilter] = useState("All issue types");
  const [notes, setNotes] = useState(workflow.reviewerNotes);
  const selected = validationResults.find((item) => item.id === selectedId) ?? validationResults[0];
  const currentStatus = selected.parcelId === workflow.parcelId ? workflow.reviewStatus : "Pending Review";
  const visible = validationResults.filter((item) => (statusFilter === "All statuses" || (item.parcelId === workflow.parcelId ? workflow.reviewStatus : "Pending Review") === statusFilter) && (riskFilter === "All risks" || item.riskLevel === riskFilter) && (issueFilter === "All issue types" || item.issueType === issueFilter));
  const action = (kind: "approve" | "escalate" | "information" | "start") => {
    const actionLabel = kind === "approve" ? "approve" : kind === "escalate" ? "escalate" : kind === "information" ? "request more information" : "start review";
    if (!window.confirm(`Are you sure you want to ${actionLabel} this case?`)) return;
    const reason = kind === "escalate" ? window.prompt("Provide reason for escalation.", "Additional officer review required.") : kind === "information" ? window.prompt("What information should the citizen provide?", "Please provide the updated ownership document.") : "";
    if ((kind === "escalate" || kind === "information") && !reason?.trim()) { toast.error("A reason or information request is required."); return; }
    const nextReview = kind === "approve" ? "Approved" : kind === "escalate" ? "Escalated" : kind === "information" ? "Need Information" : "Under Review";
    const nextRequest = kind === "approve" ? "Completed" : kind === "escalate" ? "Escalated" : kind === "information" ? "Need Information" : "Under Review";
    const event = makeWorkflowEvent(kind === "approve" ? "Case approved" : kind === "escalate" ? "Case escalated" : kind === "information" ? "Information requested from citizen" : "Review started", workflow.reviewStatus, nextReview, reason || notes);
    if (selected.parcelId === workflow.parcelId) {
      const notification = { id: `NOT-WORKFLOW-${Date.now()}`, title: kind === "approve" ? `Your request ${workflow.requestId} is completed` : kind === "information" ? "Additional information is required" : kind === "escalate" ? `Your request ${workflow.requestId} was escalated` : `Your request ${workflow.requestId} is now under review`, detail: reason || `Government review updated the linked case ${workflow.caseId}.`, read: false, createdAt: new Date().toISOString() };
      updateWorkflow({ reviewStatus: nextReview, requestStatus: nextRequest, reviewerNotes: notes, escalationReason: kind === "escalate" ? reason || "" : workflow.escalationReason, informationRequest: kind === "information" ? reason || "" : workflow.informationRequest, updatedAt: new Date().toLocaleString(), notifications: [notification, ...workflow.notifications], auditEvents: [event, ...workflow.auditEvents] });
      
      // Phase 3 explicitly requested state/context update for the parcel
      const p = demoParcels.find(p => p.id === selected.parcelId);
      if (p) {
        const updatedParcel = { ...p };
        updatedParcel.status = kind === "approve" ? "Verified" : kind === "escalate" ? "Flagged" : "Under review";
        updatedParcel.risk = kind === "approve" ? "Low" : kind === "escalate" ? "High" : "Medium";
        selectParcel(updatedParcel.id, updatedParcel);
      }
    }
    toast.success(kind === "approve" ? "Review action recorded successfully." : kind === "escalate" ? "Case escalated successfully." : kind === "information" ? "Notification sent." : "Review started successfully.");
  };
  return <><ModuleHeader eyebrow="GOVERNMENT / REVIEW & APPROVAL" title="Review & Approval" description="AI identifies possible issues. Government officers make the final accountable decision." actions={<button className="secondary-button" onClick={() => setLocation("/government/validation")}><ScanSearch size={14} /> Back to AI Validation</button>} /><div className="module-stat-grid review-summary-stats"><ModuleStat label="Pending reviews" value="18" detail="Officer action needed" icon={<Clock3 size={16} />} /><ModuleStat label="High priority" value="6" detail="High-risk cases" tone="red" icon={<ShieldAlert size={16} />} /><ModuleStat label="Under review" value={workflow.reviewStatus === "Under Review" ? "1" : "4"} detail="Assigned to officers" tone="teal" icon={<UserRound size={16} />} /><ModuleStat label="Completed reviews" value={workflow.reviewStatus === "Approved" ? "193" : "192"} detail="Synthetic district total" tone="green" icon={<CheckCircle2 size={16} />} /><ModuleStat label="Escalated" value={workflow.reviewStatus === "Escalated" ? "5" : "4"} detail="Needs senior review" tone="amber" icon={<ArrowUpRight size={16} />} /></div><div className="review-banner"><div className="review-banner-icon"><UserRound size={18} /></div><div><strong>Human review is required</strong><span>AI findings are recommendations only. Approval and escalation remain officer decisions.</span></div><span className="queue-badge">{visible.length} visible cases</span></div><div className="review-stage-strip"><span className="review-stage-active">01 · AI Detection</span><ChevronRight size={14} /><span className="review-stage-active">02 · Human Review</span><ChevronRight size={14} /><span className={currentStatus !== "Pending Review" ? "review-stage-active" : ""}>03 · {currentStatus}</span><ChevronRight size={14} /><span>04 · Citizen Update</span></div><div className="review-filter-bar surface-card"><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option>All statuses</option><option>Pending Review</option><option>Under Review</option><option>Approved</option><option>Escalated</option><option>Need Information</option></select><select value={riskFilter} onChange={(event) => setRiskFilter(event.target.value)}><option>All risks</option><option>Low</option><option>Medium</option><option>High</option></select><select value={issueFilter} onChange={(event) => setIssueFilter(event.target.value)}><option>All issue types</option><option>Land-use mismatch</option><option>Ownership mismatch</option><option>Document inconsistency</option></select><span className="review-filter-note">Case queue · synthetic records</span></div><div className="approval-layout review-workspace-layout"><SectionCard title="Review queue" kicker="CITIZEN + AI CASES">{visible.length ? <div className="approval-list">{visible.map((item) => { const itemStatus = item.parcelId === workflow.parcelId ? workflow.reviewStatus : "Pending Review"; return <button className={`approval-card approval-card-button ${selected.id === item.id ? "approval-card-active" : ""}`} key={item.id} onClick={() => { setSelectedId(item.id); selectParcel(item.parcelId); }}><div className={`validation-severity severity-${item.riskLevel.toLowerCase()}`}><ShieldAlert size={17} /></div><div className="approval-copy"><div className="validation-row-top"><strong>CASE-{item.id.slice(-4)}</strong><span className="mono-text">{item.parcelId}</span></div><p>{item.issueType} · {item.source}</p><div className="evidence-row"><span><FileCheck2 size={12} /> ULPIN {demoParcels.find((parcel) => parcel.id === item.parcelId)?.ulpin}</span><span><Clock3 size={12} /> {item.createdAt.slice(0, 10)}</span></div></div><div className="approval-actions"><span className={`risk-badge risk-${item.riskLevel.toLowerCase()}`}>{itemStatus}</span><ChevronRight size={14} /></div></button>; })}</div> : <StatePanel kind="empty" title="No cases match these filters" detail="Try clearing a filter to see the synthetic queue." />}</SectionCard><SectionCard title="Review details" kicker="EVIDENCE + DECISION"><div className="review-detail"><div className="validation-detail-head"><div className={`validation-severity severity-${selected.riskLevel.toLowerCase()}`}><ShieldAlert size={17} /></div><div><strong>{selected.issueType}</strong><span className="mono-text">CASE-{selected.id.slice(-4)} · {selected.parcelId}</span></div><span className={`risk-badge risk-${selected.riskLevel.toLowerCase()}`}>{selected.riskLevel} risk</span></div><div className="review-facts review-facts-expanded"><span>Case ID<strong>CASE-{selected.id.slice(-4)}</strong></span><span>Parcel / ULPIN<strong>{selected.parcelId} · {demoParcels.find((parcel) => parcel.id === selected.parcelId)?.ulpin}</strong></span><span>Issue / source<strong>{selected.issueType} · {selected.source}</strong></span><span>Status / reviewer<strong>{currentStatus} · {workflow.reviewer}</strong></span></div><EvidenceComparison issueType={selected.issueType} /><div className="review-evidence-stack"><div><strong>GIS / Planning Layer</strong><span>Residential planning context · synthetic GIS layer</span></div><div><strong>Satellite Observation</strong><span>Potential recent land-use change · confidence 82%</span></div><div><strong>Parcel 360° Summary</strong><span>{selected.parcelId} · {demoParcels.find((parcel) => parcel.id === selected.parcelId)?.area} · ownership record available</span></div></div><label className="review-notes-label">Reviewer Notes<textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Enter review observations..." /></label><div className="review-action-buttons"><button className="approve-button" onClick={() => action("approve")}><Check size={14} /> Approve</button><button className="escalate-button" onClick={() => action("escalate")}><ArrowUpRight size={14} /> Escalate</button><button className="secondary-button" onClick={() => action("information")}><FileCheck2 size={14} /> Request More Information</button><button className="secondary-button" onClick={() => action("start")}><Play size={14} /> Start Review</button></div><div className="review-history"><div className="card-kicker">REVIEW TIMELINE</div><TimelineEvent year="12 Sep 2026 · 10:14" title="Case created · AI finding detected" source="Validation engine" /><TimelineEvent year="12 Sep 2026 · 10:15" title="Review assigned" source="Assigned Officer" tone="amber" /><TimelineEvent year={workflow.updatedAt} title={currentStatus} source={workflow.reviewer} tone={currentStatus === "Approved" ? "green" : "blue"} /></div><button className="card-link" onClick={() => setLocation("/government/parcel")}>Open selected Parcel 360° <ArrowUpRight size={13} /></button></div></SectionCard></div></>;
}

function ReportsPage() {
  const { selectedParcel, workflow } = useLandStack();
  const [loading, setLoading] = useState(false);
  const [generated, setGenerated] = useState("Parcel Report");
  const [preview, setPreview] = useState(false);
  const reportTypes = ["Parcel Report", "AI Validation Report", "Satellite Change Report", "Review / Approval Report", "Land Governance Summary", "Citizen Service Report"];
  const generate = (type = generated) => { setGenerated(type); setLoading(true); setPreview(false); window.setTimeout(() => { setLoading(false); setPreview(true); toast.success("Report generated successfully.", { description: `${type} · synthetic report preview ready.` }); }, 650); };
  return <><ModuleHeader eyebrow="GOVERNMENT / REPORTS" title="Reports" description="Generate explainable parcel, validation, satellite, review and citizen service summaries." actions={<button className="primary-button" onClick={() => generate()}>{loading ? <RotateCcw size={14} className="state-spin" /> : <Plus size={14} />} {loading ? "Generating report..." : "Generate report"}</button>} /><div className="report-type-grid report-type-grid-expanded">{reportTypes.map((type, index) => <button key={type} className={`report-type-card ${generated === type ? "report-type-card-active" : ""}`} onClick={() => generate(type)}><div className={`report-type-icon report-type-${(index % 4) + 1}`}><FileCheck2 size={18} /></div><strong>{type}</strong><span>{index === 0 ? "One parcel · complete identity" : index === 1 ? "Explainable findings" : index === 2 ? "Before / after evidence" : index === 3 ? "Human decisions" : index === 4 ? "District overview" : "Citizen request status"}</span><ArrowUpRight size={15} /></button>)}</div>{preview && <SectionCard title={`${generated} · Preview`} kicker="SYNTHETIC REPORT" action={<button className="secondary-button" onClick={() => toast.success("Download prepared")}><Download size={14} /> Download</button>}><div className="report-preview"><div className="report-preview-head"><div><span className="mono-text">RPT-DEMO-{generated.slice(0, 3).toUpperCase()} · 22 Sep 2026</span><h2>{generated}</h2></div><span className="status-badge status-verified"><span />Ready</span></div>{generated === "Parcel Report" ? <div className="report-facts-grid"><span>Parcel ID<strong>{selectedParcel.id}</strong></span><span>ULPIN<strong>{selectedParcel.ulpin}</strong></span><span>Area / location<strong>{selectedParcel.area} · {selectedParcel.locality}</strong></span><span>Land use / ownership<strong>{selectedParcel.landUse} · Verified</strong></span><span>AI validation<strong>{workflow.issue}</strong></span><span>Satellite<strong>Potential change detected · 82% confidence</strong></span><span>Risk summary<strong>{workflow.risk} · human review required</strong></span><span>Review status<strong>{workflow.reviewStatus}</strong></span></div> : <div className="report-facts-grid"><span>Scope<strong>West district · 5 synthetic parcels</strong></span><span>Issues detected<strong>4 validation findings · 1 high risk</strong></span><span>Selected parcel<strong>{selectedParcel.id} · {workflow.ulpin}</strong></span><span>Review status<strong>{workflow.reviewStatus} · {workflow.reviewer}</strong></span><span>Citizen request<strong>{workflow.requestId} · {workflow.requestStatus}</strong></span><span>Generated by<strong>A. Officer · Government Portal</strong></span></div>}<div className="report-demo-note"><ShieldAlert size={14} /><span>This report is a polished prototype preview using synthetic data. It does not represent an official approval or real government record.</span></div></div></SectionCard>}<SectionCard title="Recent reports" kicker="REPORT LIBRARY" action={<button className="filter-button" onClick={() => toast.info("Report filters are staged for the backend integration")}><Filter size={14} /> Filter</button>}><div className="report-table">{[...reports, { id: "RPT-DEMO-NEW", type: generated as any, scope: selectedParcel.id, status: preview ? "Ready" : "Generating", createdAt: "22 Sep 2026" } as any].map((report) => <div className="report-row" key={`${report.id}-${report.type}`}><div className="report-file-icon"><FileCheck2 size={16} /></div><div className="report-row-main"><strong>{report.type}</strong><span className="mono-text">{report.id} · {report.scope}</span></div><span className={`status-badge ${report.status === "Ready" ? "status-verified" : report.status === "Generating" ? "status-review" : "status-flagged"}`}><span />{report.status}</span><span className="report-date">{report.createdAt}</span><button className="table-more" onClick={() => report.status === "Ready" ? setPreview(true) : toast.error("Report is still generating", { description: "Please try again shortly." })}><Download size={15} /></button></div>)}</div></SectionCard></>;
}

function AnalyticsPage() { const landUse = [{ label: "Residential", value: 44, color: "#2c6ce6" }, { label: "Agricultural", value: 26, color: "#2b9b68" }, { label: "Commercial", value: 16, color: "#c68322" }, { label: "Mixed use", value: 9, color: "#129d98" }, { label: "Institutional", value: 5, color: "#8171c7" }]; return <><ModuleHeader eyebrow="GOVERNMENT / ANALYTICS" title="Land intelligence analytics" description="A concise operational view of parcel coverage, validation risk and workflow throughput." actions={<button className="secondary-button" onClick={() => toast.info("Analytics snapshot export is staged")}><ArrowDownToLine size={14} /> Export snapshot</button>} /><div className="analytics-grid"><SectionCard title="Parcels by land use" kicker="12,486 INDEXED"><div className="donut-chart"><div className="donut-hole"><strong>5</strong><span>classes</span></div></div><div className="chart-legend">{landUse.map((item) => <span key={item.label}><i style={{ background: item.color }} />{item.label}<strong>{item.value}%</strong></span>)}</div></SectionCard><SectionCard title="Validation issues" kicker="LAST 30 DAYS"><div className="bar-chart">{[58, 42, 69, 31, 48, 76, 52].map((value, index) => <div className="bar-column" key={index}><div className="bar-value" style={{ height: `${value}%` }} /><span>{["18", "20", "22", "24", "26", "28", "30"][index]}</span></div>)}</div><div className="chart-summary"><strong>34</strong><span>issues detected</span><em><TrendingUp size={12} /> 8.2% vs. previous period</em></div></SectionCard><SectionCard title="Risk distribution" kicker="ACTIVE PARCELS"><div className="risk-distribution"><div><span>Low</span><div><i className="risk-fill-low" style={{ width: "74%" }} /></div><strong>74%</strong></div><div><span>Medium</span><div><i className="risk-fill-medium" style={{ width: "21%" }} /></div><strong>21%</strong></div><div><span>High</span><div><i className="risk-fill-high" style={{ width: "5%" }} /></div><strong>5%</strong></div></div></SectionCard><SectionCard title="Review throughput" kicker="WORKFLOW STATUS"><div className="throughput-number"><strong>87%</strong><span>resolved within target</span></div><div className="throughput-track"><i style={{ width: "87%" }} /></div><div className="throughput-meta"><span>192 resolved</span><span>26 open</span></div></SectionCard></div></>;
}

function AuditPage() {
  const { workflow } = useLandStack();
  const [search, setSearch] = useState("");
  const [role, setRole] = useState("All roles");
  const [module, setModule] = useState("All modules");
  const [selected, setSelected] = useState<any>(null);
  const workflowRows = workflow.auditEvents.map((event) => ({ id: event.id, timestamp: event.timestamp, actor: event.actor, role: event.role, action: event.action, module: event.module, parcelId: event.parcelId, caseId: event.caseId, previousStatus: event.previousStatus, newStatus: event.newStatus, detail: event.detail }));
  const initialRows = auditLogs.map((log) => ({ id: log.id, timestamp: log.timestamp, actor: log.actor, role: log.role, action: log.action, module: log.entityType, parcelId: log.entityId, caseId: log.entityType === "Request" ? log.entityId : undefined, previousStatus: "—", newStatus: "Recorded", detail: "Synthetic audit event from the Data layer." }));
  const rows = [...workflowRows, ...initialRows];
  const filtered = rows.filter((log) => `${log.actor} ${log.action} ${log.parcelId} ${log.caseId ?? ""}`.toLowerCase().includes(search.toLowerCase()) && (role === "All roles" || log.role === role) && (module === "All modules" || log.module === module));
  return <><ModuleHeader eyebrow="GOVERNMENT / AUDIT LOGS" title="Audit Logs" description="A government-only record of review actions, request updates, reports and notifications." actions={<button className="secondary-button" onClick={() => toast.success("Audit export prepared for the platform")}><ArrowDownToLine size={14} /> Export logs</button>} /><div className="module-stat-grid"><ModuleStat label="Total events" value={`${rows.length}`} detail="Synthetic immutable events" icon={<CheckCircle2 size={16} />} /><ModuleStat label="Review actions" value={`${workflow.auditEvents.length}`} detail="Current demo case" tone="teal" icon={<ShieldAlert size={16} />} /><ModuleStat label="Citizen updates" value={`${workflow.notifications.length}`} detail="Notifications created" tone="amber" icon={<BellIcon />} /></div><SectionCard title="Governance activity" kicker="IMMUTABLE EVENTS" action={<div className="audit-filters"><SearchField value={search} onChange={setSearch} placeholder="Search parcel, case, action" /><select value={role} onChange={(event) => setRole(event.target.value)}><option>All roles</option><option value="government">Government</option><option value="citizen">Citizen</option><option value="system">System</option></select><select value={module} onChange={(event) => setModule(event.target.value)}><option>All modules</option><option>Review / Approval</option><option>Parcel</option><option>Validation</option><option>Request</option><option>Report</option></select></div>}><div className="audit-table"><div className="audit-head"><span>Timestamp</span><span>User</span><span>Role</span><span>Action</span><span>Module / parcel</span><span>Status</span></div>{filtered.map((log) => <button className="audit-row audit-row-button" key={log.id} onClick={() => setSelected(log)}><span className="mono-text">{log.timestamp.replace("T", " ").replace("Z", "").slice(0, 19)}</span><strong>{log.actor}</strong><span className={`role-badge role-${log.role}`}>{log.role}</span><span>{log.action}</span><span><b>{log.module}</b><small className="mono-text">{log.parcelId}</small></span><span className="status-badge status-verified"><span />{log.newStatus}</span></button>)}{!filtered.length && <StatePanel kind="empty" title="No audit events match" detail="Try clearing the search or filters." />}</div></SectionCard>{selected && <div className="audit-detail-panel surface-card"><div className="card-heading"><div><div className="card-kicker">AUDIT EVENT DETAIL</div><h2>{selected.action}</h2></div><button className="icon-button" onClick={() => setSelected(null)}><X size={16} /></button></div><div className="audit-detail-grid"><span>Timestamp<strong>{selected.timestamp}</strong></span><span>Actor / role<strong>{selected.actor} · {selected.role}</strong></span><span>Module / parcel<strong>{selected.module} · {selected.parcelId}</strong></span><span>Case / request<strong>{selected.caseId ?? workflow.caseId}</strong></span><span>Previous status<strong>{selected.previousStatus ?? "—"}</strong></span><span>New status<strong>{selected.newStatus ?? "Recorded"}</strong></span><span>Additional information<strong>{selected.detail ?? "Synthetic audit event."}</strong></span></div></div>}</>;
}
function BellIcon() { return <CheckCircle2 size={16} />; }
